#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int to, weight, next;
} Edge;

typedef struct {
    long long d;
    int v;
} HeapNode;

int *parent, *sz;
int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

HeapNode *heap;
int heapSize = 0;

void heapPush(long long d, int v) {
    int i = heapSize++;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].d <= d) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i].d = d;
    heap[i].v = v;
}

HeapNode heapPop(void) {
    HeapNode res = heap[0];
    heapSize--;
    if (heapSize > 0) {
        HeapNode last = heap[heapSize];
        int i = 0;
        while (1) {
            int l = 2 * i + 1;
            int r = l + 1;
            int smallest = i;
            if (l < heapSize && heap[l].d < heap[smallest].d) smallest = l;
            if (r < heapSize && heap[r].d < heap[smallest].d) smallest = r;
            if (smallest == i) break;
            heap[i] = heap[smallest];
            i = smallest;
        }
        heap[i] = last;
    }
    return res;
}

