            int u = oU[idx], v = oV[idx];
            int a = find(u), b = find(v);

            if (a != b) {
                if (sz[a] < sz[b]) {
                    int tmp = a;
                    a = b;
                    b = tmp;
                }
                parent[b] = a;
                sz[a] += sz[b];
            }
        }

        for (int i = 0; i < top; i++) {
            int v = touched[i];
