            weight[edgeCnt] = P[c];
            nxt[edgeCnt] = head[v];
            head[v] = edgeCnt++;

            to[edgeCnt] = v;
            weight[edgeCnt] = 0;
            nxt[edgeCnt] = head[compNode];
            head[compNode] = edgeCnt++;
        }
    }

    int A, B;
    scanf("%d %d", &A, &B);

    int totalNodes = N + compCnt;
    long long INF = 1000000000000000000LL;
    long long *dist = (long long*) malloc((totalNodes + 1) * sizeof(long long));

    for (int i = 1; i <= totalNodes; i++) dist[i] = INF;

    heap = (HeapNode*) malloc((edgeCnt + 5) * sizeof(HeapNode));
    heapSize = 0;

    dist[A] = 0;
    heapPush(0, A);

    while (heapSize > 0) {
        HeapNode curNode = heapPop();
        long long d = curNode.d;
        int u = curNode.v;

        if (d != dist[u]) continue;
        if (u == B) break;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            long long nd = d + weight[e];

            if (nd < dist[v]) {
                dist[v] = nd;
                heapPush(nd, v);
            }
        }
    }

    if (dist[B] >= INF / 2) printf("-1\n");
    else printf("%lld\n", dist[B]);

    return 0;
